const fs = require('fs');
const path = require('path');
const { IOSConfig, withDangerousMod, withXcodeProject } = require('expo/config-plugins');

// Alternate iOS app icons: every Icon Composer bundle in assets/brand/app-icons
// (generated by scripts/generate-app-icons.ts) is copied beside the primary
// .icon, added to the app target's resources and named as an alternate, so
// actool lists it under CFBundleAlternateIcons. Android is left unchanged.
const SOURCE = path.join('assets', 'brand', 'app-icons');
const iconNames = projectRoot => {
  const folder = path.join(projectRoot, SOURCE);
  if (!fs.existsSync(folder)) return [];
  return fs.readdirSync(folder).filter(name => name.endsWith('.icon')).map(name => path.basename(name, '.icon')).sort();
};

module.exports = config => {
  config = withDangerousMod(config, ['ios', async config => {
    const { projectRoot, platformProjectRoot, projectName } = config.modRequest;
    for (const name of iconNames(projectRoot)) {
      const target = path.join(platformProjectRoot, projectName, `${name}.icon`);
      await fs.promises.rm(target, { recursive: true, force: true });
      await fs.promises.cp(path.join(projectRoot, SOURCE, `${name}.icon`), target, { recursive: true });
    }
    return config;
  }]);
  return withXcodeProject(config, config => {
    const { projectRoot, projectName } = config.modRequest, project = config.modResults, names = iconNames(projectRoot);
    if (!names.length) return config;
    for (const name of names) {
      IOSConfig.XcodeUtils.addResourceFileToGroup({ filepath: `${projectName}/${name}.icon`, groupName: projectName, project, isBuildFile: true, verbose: false });
    }
    const [, target] = IOSConfig.Target.findNativeTargetByName(project, projectName);
    for (const [, build] of IOSConfig.XcodeUtils.getBuildConfigurationsForListId(project, target.buildConfigurationList)) {
      if (build?.buildSettings) build.buildSettings.ASSETCATALOG_COMPILER_ALTERNATE_APPICON_NAMES = `"${names.join(' ')}"`;
    }
    return config;
  });
};
